1	package org.springframework.samples.petclinic.model;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	/**
8	 * Single source of truth for an owner's {@code memberId} and the values derived from it. The member id
9	 * unifies the former {@code customerCode} and {@code membershipNumber} into one identifier of the shape
10	 * {@code <REGION><FY><HASH8><CHK>}:
11	 *
12	 * <ul>
13	 * <li>{@code REGION} - the region code derived from the postcode (see
14	 * {@link org.springframework.samples.petclinic.mapper.Regions#regionForPostcode(String)}, e.g.
15	 * {@code NSW}, or {@code UNKNOWN} when the postcode resolves to no known region);</li>
16	 * <li>{@code FY} - the two-digit fiscal-year start year of the owner's (business-day-adjusted)
17	 * registration date (see {@link FiscalYear#twoDigitStartYear});</li>
18	 * <li>{@code HASH8} - the first 8 upper-case hex characters of
19	 * {@code SHA-256(normalizedTelephone + lastName)} (see {@link #hash8(String, String)}), the same hash
20	 * used by the region-and-hash identity;</li>
21	 * <li>{@code CHK} - a single Luhn check digit over the digits of {@code <REGION><FY><HASH8>}.</li>
22	 * </ul>
23	 *
24	 * <p>The format is assembled by {@link #format(String, String, String)} and the region read back by
25	 * {@link #region(String)}; both sit here so the ordering and the check-digit scope live as one matched
26	 * pair. There is no separator between components, so {@link #region(String)} recovers the region as the
27	 * leading run of non-digit characters (the fiscal year that follows is always digits).
28	 */
29	public final class MemberId {
30	
31	    /** The single character separating a de-duplication suffix from the base member id. */
32	    private static final char SEPARATOR = '-';
33	
34	    /** The region string used when a postcode (or a stored member id) resolves to no known region. The
35	     *  canonical definition of this sentinel, which {@code Regions.UNKNOWN} also points at so the region
36	     *  a member id is built with and the region read back out can never diverge. */
37	    public static final String UNKNOWN_REGION = "UNKNOWN";
38	
39	    private MemberId() {
40	    }
41	
42	    /**
43	     * Assemble a {@code <REGION><FY><HASH8><CHK>} member id from its components. The check digit is the
44	     * Luhn digit (see {@link #checkDigit(String)}) over the digits of the concatenated
45	     * {@code <REGION><FY><HASH8>} base.
46	     *
47	     * @param region    the region code (typically {@code Regions.regionForPostcode(...)})
48	     * @param fiscalYear the two-digit fiscal-year start year (see {@link FiscalYear#twoDigitStartYear})
49	     * @param hash8      the 8-character hash component (see {@link #hash8(String, String)})
50	     * @return the assembled member id
51	     */
52	    public static String format(String region, String fiscalYear, String hash8) {
53	        String base = region + fiscalYear + hash8;
54	        return base + checkDigit(base);
55	    }
56	
57	    /**
58	     * Spell a de-duplicated member id by appending a numeric suffix to {@code base}, joined with the
59	     * {@link #SEPARATOR}. Used when a computed member id collides with an existing owner's: callers try
60	     * {@code n} of 2, 3, ... until the result is unique (e.g. {@code NSW261A2B3C4D7-2}).
61	     *
62	     * @param base the colliding base member id to disambiguate
63	     * @param n    the suffix number (2 or more)
64	     * @return {@code base}, the separator and {@code n}
65	     */
66	    public static String withSuffix(String base, int n) {
67	        return base + SEPARATOR + n;
68	    }
69	
70	    /**
71	     * Compute the {@code HASH8} component: the first 8 upper-case hex characters of
72	     * {@code SHA-256(normalizedTelephone + lastName)}, where the telephone is normalized to E.164 form
73	     * (see {@link OwnerTelephone#toE164(String)}) exactly as the owner's identity key is, so the hash
74	     * over a submitted and a stored owner can never silently diverge.
75	     *
76	     * @param telephone the owner's telephone; normalized to E.164 before hashing
77	     * @param lastName  the owner's last name
78	     * @return the 8 upper-case hex characters
79	     */
80	    public static String hash8(String telephone, String lastName) {
81	        String normalizedTelephone = OwnerTelephone.toE164(telephone);
82	        if (normalizedTelephone == null) {
83	            normalizedTelephone = telephone == null ? "" : telephone;
84	        }
85	        String last = lastName == null ? "" : lastName;
86	        return sha256UpperHex(normalizedTelephone + last).substring(0, 8);
87	    }
88	
89	    /**
90	     * Read the {@code REGION} component back out of a member id: the leading run of non-digit
91	     * characters, before the two-digit fiscal year. This is the single source of truth for the
92	     * {@code locality} response field, so the locality an owner reports is exactly the region baked into
93	     * its identity.
94	     *
95	     * @param memberId the member id; may be {@code null}
96	     * @return the region prefix, or {@link #UNKNOWN_REGION} when the member id is {@code null} or starts
97	     *         with no region (its first character is already a digit)
98	     */
99	    public static String region(String memberId) {
100	        if (memberId == null) {
101	            return UNKNOWN_REGION;
102	        }
103	        int i = 0;
104	        while (i < memberId.length() && !Character.isDigit(memberId.charAt(i))) {
105	            i++;
106	        }
107	        return i == 0 ? UNKNOWN_REGION : memberId.substring(0, i);
108	    }
109	
110	    /**
111	     * Compute the Luhn check digit over the digits contained in {@code value}. An implementation detail
112	     * of {@link #format(String, String, String)}, which embeds it as the member id's {@code CHK}
113	     * segment; the digit is not otherwise exposed.
114	     *
115	     * @param value the value; non-digit characters are ignored
116	     * @return the Luhn check digit, between 0 and 9 inclusive
117	     */
118	    private static int checkDigit(String value) {
119	        int sum = 0;
120	        boolean dbl = true;
121	        for (int i = value.length() - 1; i >= 0; i--) {
122	            char c = value.charAt(i);
123	            if (c < '0' || c > '9') {
124	                continue;
125	            }
126	            int d = c - '0';
127	            if (dbl) {
128	                d *= 2;
129	                if (d > 9) {
130	                    d -= 9;
131	                }
132	            }
133	            sum += d;
134	            dbl = !dbl;
135	        }
136	        return (10 - (sum % 10)) % 10;
137	    }
138	
139	    /** Full upper-case hex SHA-256 of the UTF-8 bytes of {@code s}. */
140	    private static String sha256UpperHex(String s) {
141	        try {
142	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8));
143	            StringBuilder sb = new StringBuilder(digest.length * 2);
144	            for (byte b : digest) {
145	                sb.append(String.format("%02X", b));
146	            }
147	            return sb.toString();
148	        }
149	        catch (NoSuchAlgorithmException ex) {
150	            throw new IllegalStateException("SHA-256 not available", ex);
151	        }
152	    }
153	}
