1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.MembershipLevel;
5	import org.springframework.samples.petclinic.model.Owner;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	
8	/**
9	 * Runs after {@link AssignHousehold} (so the {@code householdId} is set) and before
10	 * {@link SaveOwner} on {@code POST /api/owners}. Caps the new owner's membership level so it cannot
11	 * exceed one above the current maximum {@link MembershipLevel level} among the existing members of
12	 * the owner's household (the already-saved owners sharing the same {@code householdId}).
13	 *
14	 * <p>The computed ceiling is stored on the owner as its
15	 * {@link Owner#getMembershipLevelCap() membership level cap}; {@link MembershipLevel#of(Owner)} then
16	 * applies it whenever the level is derived, so the capped value is what every response returns. When
17	 * the household has no existing member — no match, or the owner has no {@code householdId} (no
18	 * postcode) — no cap applies and the owner keeps its uncapped level.
19	 */
20	public class CapMembershipLevel {
21	
22	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
23	        String householdId = owner.getHouseholdId();
24	        if (householdId == null) {
25	            return; // no household to key on, so no cap
26	        }
27	        Integer maxLevel = null;
